INSERT INTO event (event_id, event_name, description, start_at, end_at, location, status, round_no, image_url, base_fee, organizer, organizer_phone, organizer_email) VALUES
('1', '서울 펫 페스티벌', '도심 속에서 펼쳐지는 최대 규모의 반려동물 축제입니다.', '2026-05-29 09:00:00', '2026-06-08 18:00:00', 'COEX', 'ONGOING', NULL, 'https://pupoo-uploads-kgj.s3.ap-northeast-2.amazonaws.com/image/seoul-pet-pestival.png', '15000.0', '푸푸 페스티벌 조직위원회', '010-4977-5002', 'organizer1@pupoo.com'),
('2', '부산 펫 페어', '바다의 도시 부산에서 열리는 펫 산업 박람회입니다.', '2026-05-30 09:00:00', '2026-06-09 18:00:00', '벡스코', 'ONGOING', NULL, 'https://pupoo-uploads-kgj.s3.ap-northeast-2.amazonaws.com/image/busan-pet-fair.png', '10000.0', '푸푸 페스티벌 조직위원회', '010-4393-7384', 'organizer2@pupoo.com'),
('3', '코리아 펫 엑스포', '전국의 반려동물 기업과 보호자가 함께하는 엑스포입니다.', '2026-05-28 09:00:00', '2026-06-17 18:00:00', '킨텍스', 'ONGOING', NULL, 'https://pupoo-uploads-kgj.s3.ap-northeast-2.amazonaws.com/image/korea-pet-expo.png', '12000.0', '푸푸 페스티벌 조직위원회', '010-5868-7482', 'organizer3@pupoo.com'),
('4', '대구 반려동물 박람회', '대구에서 열리는 가족친화적 반려동물 박람회입니다.', '2026-05-27 09:00:00', '2026-06-16 18:00:00', 'EXCO', 'ONGOING', NULL, 'https://pupoo-uploads-kgj.s3.ap-northeast-2.amazonaws.com/image/daegu-pet-fair.png', '8000.0', '푸푸 페스티벌 조직위원회', '010-8379-2448', 'organizer4@pupoo.com'),
('5', '광주 펫 쇼', '광주에서 반려동물과 함께 즐기는 체험과 이벤트가 가득!', '2026-06-20 09:00:00', '2026-07-03 18:00:00', '김대중컨벤션센터', 'PLANNED', NULL, 'uploads/event/event_5.jpg', '8000.0', '푸푸 페스티벌 조직위원회', '010-5464-7416', 'organizer5@pupoo.com'),
('6', '수원 펫 페어', '경기도 수원에서 열리는 대규모 펫 박람회입니다.', '2026-07-01 09:00:00', '2026-07-11 18:00:00', '수원컨벤션센터', 'PLANNED', NULL, 'uploads/event/event_6.jpg', '11000.0', '푸푸 페스티벌 조직위원회', '010-2741-2092', 'organizer6@pupoo.com'),
('7', '인천 반려동물 축제', '송도 컨벤시아에서 열리는 즐거운 반려동물 축제입니다.', '2026-05-10 09:00:00', '2026-05-23 18:00:00', '송도 컨벤시아', 'ENDED', NULL, 'uploads/event/event_7.jpg', '9000.0', '푸푸 페스티벌 조직위원회', '010-8625-2471', 'organizer7@pupoo.com'),
('8', '제주 펫 페스티벌', '제주도의 자연과 함께하는 반려동물 문화 축제입니다.', '2025-12-01 09:00:00', '2025-12-05 18:00:00', '제주국제컨벤션센터', 'ENDED', NULL, 'https://pupoo-uploads-kgj.s3.ap-northeast-2.amazonaws.com/image/jeju-pet-fair.png', '10000.0', '푸푸 페스티벌 조직위원회', '010-6935-5508', 'organizer8@pupoo.com'),
('9', '대한민국 펫 박람회', '반려동물과 함께하는 전국 박람회로 다양한 부스가 참여합니다.', '2025-11-10 09:00:00', '2025-11-15 18:00:00', '킨텍스', 'ENDED', NULL, 'https://pupoo-uploads-kgj.s3.ap-northeast-2.amazonaws.com/image/korea-pet-fair.png', '12000.0', '푸푸 페스티벌 조직위원회', '010-2355-9265', 'organizer9@pupoo.com'),
('10', '반려동물 라이프스타일 페어', '반려동물 라이프스타일을 제안하는 체험형 박람회입니다.', '2025-10-05 09:00:00', '2025-10-10 18:00:00', 'COEX', 'ENDED', NULL, 'https://pupoo-uploads-kgj.s3.ap-northeast-2.amazonaws.com/image/pet-lifestayle-fair.png', '9000.0', '푸푸 페스티벌 조직위원회', '010-7223-1810', 'organizer10@pupoo.com'),
('11', '한국 반려동물 박람회', '한국을 대표하는 반려동물 박람회로 다양한 세미나와 체험을 제공합니다.', '2025-09-01 09:00:00', '2025-09-06 18:00:00', '킨텍스', 'ENDED', NULL, 'uploads/event/event_11.jpg', '13000.0', '푸푸 페스티벌 조직위원회', '010-1705-4347', 'organizer11@pupoo.com'),
('12', '펫케어 전시회', '건강관리와 미용을 중심으로 한 펫케어 전문 전시회입니다.', '2025-08-20 09:00:00', '2025-08-24 18:00:00', '벡스코', 'ENDED', NULL, 'uploads/event/event_12.jpg', '7000.0', '푸푸 페스티벌 조직위원회', '010-6851-1351', 'organizer12@pupoo.com'),
('13', '울산 펫 페어', '울산에서 처음 열리는 반려동물 축제입니다.', '2026-06-25 09:00:00', '2026-06-30 18:00:00', '울산전시컨벤션센터', 'PLANNED', NULL, 'https://pupoo-uploads-kgj.s3.ap-northeast-2.amazonaws.com/image/ulsan-pet-fair.png', '10000.0', '푸푸 페스티벌 조직위원회', '010-2916-5390', 'organizer13@pupoo.com'),
('14', '세종 반려동물 축제', '세종시에서 열리는 지역 반려동물 페스티벌입니다.', '2026-07-10 09:00:00', '2026-07-15 18:00:00', '세종컨벤션센터', 'PLANNED', NULL, 'uploads/event/event_14.jpg', '8000.0', '푸푸 페스티벌 조직위원회', '010-1921-1561', 'organizer14@pupoo.com'),
('15', '충청 펫 박람회', '충청 지역 반려동물 보호자를 위한 다채로운 박람회입니다.', '2026-08-01 09:00:00', '2026-08-05 18:00:00', '대전컨벤션센터', 'PLANNED', NULL, 'uploads/event/event_15.jpg', '9000.0', '푸푸 페스티벌 조직위원회', '010-6626-8836', 'organizer15@pupoo.com');
